#' lrmodel_summary
#'
#' Summarizes results from a linear regression model
#' @param model a linear regression model object generated by lrmodel
#' @return a formatted summary of the linear regression model results, including:
#'
#' - Model call
#' - Distribution of residuals
#' - Table of coefficients, standard errors, t statistics, and p-values
#' - Residual standard error
#' - Multiple R-squared and adjusted R-squared
#' - F-statistic
#'
#' @examples
#' model1 <- lrmodel(mpg ~ wt, data = mtcars)
#' lrmodel_summary(model1)
#' @export

lrmodel_summary <- function(model) {
  # call
  call <- model$call

  # residuals
  res_summary <- summary(model$residuals)[-4]

  # model coefficients
  est <- model$coefficients

  # coefficient standard errors
  covariates <- paste(colnames(model$model[-1]), collapse = " + ")
  x <- model.matrix(as.formula(paste("~", covariates)), data = model$model)
  n_param <- model$rank
  rss <- sum((model$model[, 1] - model$fitted.values)^2)
  n = nrow(model$model)
  res_var <- rss/(n - n_param)
  se <- sqrt(res_var*diag(solve(t(x)%*%x)))

  # t value
  t <- est/se

  # p value
  p <- pt(abs(t), df = model$df.residual, lower.tail = F)*2

  # Table of coefficients
  coef_tbl <- cbind(
    "Estimate" = est, "Std. Error" = se, "t value" = t, `Pr(>|t|)` = p
  )

  # Residual se and df
  res_se <- sqrt(res_var)
  res_df <- model$df.residual

  # number of observations deleted due to missingness
  n_obs_del <- model$n_obs_del

  # R-squared
  sse = sum((model$residuals)^2)
  y = model$model[, 1]
  sst = sum((y - mean(y))^2)
  rsq = 1 - (sse/sst)
  adj_rsq = 1 - (1 - rsq)*((n - 1)/(n - n_param))

  # F-statistic
  ssr = sum((model$fitted.values - mean(y))^2)
  f = (ssr/(n_param - 1))/(sse/(n - n_param))
  f_df1 = n_param - 1
  p_f = pf(f, f_df1, res_df, lower.tail = F)

  # Formatted summary
  cat("Call:\n")
  print(call)
  cat("\n")
  cat("Residuals:\n")
  print(res_summary)
  cat("\n")
  cat("Coefficients:\n")
  print(
    coef_tbl
  )
  cat("\n")
  cat("Residual standard error:", res_se, "on", res_df, "degrees of freedom\n")
  cat("(", n_obs_del, " observations deleted due to missingness)\n", sep = "")
  cat("Multiple R-squared:", rsq, ",  Adjusted R-squared:", adj_rsq, "\n")
  cat("F-statistic:", f, "on", f_df1, "and", res_df, "DF,", "p-value:", p_f)

  # Store results in a list
  summary_results <- list(
    call = model$call,
    residuals = model$residuals,
    coefficients = coef_tbl,
    sigma = res_se,
    r.squared = rsq,
    adj.r.squared = adj_rsq,
    fstatistic = c("value" = f, "numdf" = f_df1, "dendf" = res_df)
  )

  invisible(summary_results)
}
